      project: {
        id: projectId,
        name: this.paths.descriptor.name,
        graphRevision: this.project().graph_revision,
        root: this.paths.projectRoot
      },
      changeSequence,
      blocks,
      chains,
      plans,
      links,
      chainNodes,
      chainEdges,
      planChainRefs,
      planDependencies,
      planSteps,
      planCheckpointRefs,
      planChainScopes,
      planChanges,
      planChainChangeRefs,
      backgroundScopes,
      decisions,
      decisionScopes,
      sourceRefs,
      checkpoints,
      checkpointBindings,
      checkpointDependencies,
